jedi.plugins.pytest._iter_pytest_modules:
@inference_state_method_cache()
def _iter_pytest_modules(module_context, skip_own_module=False):
    if not skip_own_module:
        yield module_context
    file_io = module_context.get_value().file_io
    if file_io is not None:
        folder = file_io.get_parent_folder()
        sys_path = module_context.inference_state.get_sys_path()
        last_folder = None
        while any((folder.path.startswith(p) for p in sys_path)):
            file_io = folder.get_file_io('conftest.py')
            if Path(file_io.path) != module_context.py__file__():
                try:
                    m = load_module_from_path(module_context.inference_state, file_io)
                    conftest_module = m.as_context()
                    yield conftest_module
                    plugins_list = m.tree_node.get_used_names().get('pytest_plugins')
                    if plugins_list:
                        name = conftest_module.create_name(plugins_list[0])
                        yield from _load_pytest_plugins(module_context, name)
                except FileNotFoundError:
                    pass
            folder = folder.get_parent_folder()
            if (last_folder is not None and folder.path == last_folder.path):
                break
            last_folder = folder
    for names in _PYTEST_FIXTURE_MODULES + _find_pytest_plugin_modules():
        for module_value in module_context.inference_state.import_module(names):
            yield module_value.as_context()

jedi.plugins.pytest._load_pytest_plugins:
def _load_pytest_plugins(module_context, name):
    from jedi.inference.helpers import get_str_or_none
    for inferred in name.infer():
        for seq_value in inferred.py__iter__():
            for value in seq_value.infer():
                fq_name = get_str_or_none(value)
                if fq_name:
                    names = fq_name.split('.')
                    for module_value in module_context.inference_state.import_module(names):
                        yield module_value.as_context()

jedi.plugins.pytest._goto_pytest_fixture:
def _goto_pytest_fixture(module_context, name, skip_own_module):
    for module_context in _iter_pytest_modules(module_context, skip_own_module=skip_own_module):
        names = FixtureFilter(module_context).get(name)
        if names:
            return names

jedi.inference.imports.load_module_from_:
def load_module_from_path(inference_state, file_io, import_names=None, is_package=None):
    """
    This should pretty much only be used for get_modules_containing_name. It's
    here to ensure that a random path is still properly loaded into the Jedi
    module structure.
    """
    path = Path(file_io.path)
    if import_names is None:
        e_sys_path = inference_state.get_sys_path()
        (import_names, is_package) = sys_path.transform_path_to_dotted(e_sys_path, path)
    else:
        assert isinstance(is_package, bool)
    is_stub = path.suffix == '.pyi'
    if is_stub:
        folder_io = file_io.get_parent_folder()
        if folder_io.path.endswith('-stubs'):
            folder_io = FolderIO(folder_io.path[:-6])
        if path.name == '__init__.pyi':
            python_file_io = folder_io.get_file_io('__init__.py')
        else:
            python_file_io = folder_io.get_file_io(import_names[-1] + '.py')
        try:
            v = load_module_from_path(inference_state, python_file_io, import_names, is_package=is_package)
            values = ValueSet([v])
        except FileNotFoundError:
            values = NO_VALUES
        return create_stub_module(inference_state, inference_state.latest_grammar, values, parse_stub_module(inference_state, file_io), file_io, import_names)
    else:
        module = _load_python_module(inference_state, file_io, import_names=import_names, is_package=is_package)
        inference_state.module_cache.add(import_names, ValueSet([module]))
        return module

jedi.plugins.pytest._find_pytest_plugin_:
def _find_pytest_plugin_modules() -> List[List[str]]:
    """
    Finds pytest plugin modules hooked by setuptools entry points

    See https://docs.pytest.org/en/stable/how-to/writing_plugins.html#setuptools-entry-points
    """
    if sys.version_info >= (3, 8):
        from importlib.metadata import entry_points
        if sys.version_info >= (3, 10):
            pytest_entry_points = entry_points(group='pytest11')
        else:
            pytest_entry_points = entry_points().get('pytest11', ())
        if sys.version_info >= (3, 9):
            return [ep.module.split('.') for ep in pytest_entry_points]
        else:
            matches = [ep.pattern.match(ep.value) for ep in pytest_entry_points]
            return [x.group('module').split('.') for x in matches if x]
    else:
        from pkg_resources import iter_entry_points
        return [ep.module_name.split('.') for ep in iter_entry_points(group='pytest11')]

jedi.api.environment.find_system_environ:
def find_system_environments(*, env_vars=None):
    """
    Ignores virtualenvs and returns the Python versions that were installed on
    your system. This might return nothing, if you're running Python e.g. from
    a portable version.

    The environments are sorted from latest to oldest Python version.

    :yields: :class:`.Environment`
    """
    for version_string in _SUPPORTED_PYTHONS:
        try:
            yield get_system_environment(version_string, env_vars=env_vars)
        except InvalidPythonEnvironment:
            pass

jedi.api.environment._calculate_sha256_f:
def _calculate_sha256_for_file(path):
    sha256 = hashlib.sha256()
    with open(path, 'rb') as f:
        for block in iter(lambda: f.read(filecmp.BUFSIZE), b''):
            sha256.update(block)
    return sha256.hexdigest()

jedi.api.environment._is_safe:
def _is_safe(executable_path):
    real_path = os.path.realpath(executable_path)
    if _is_unix_safe_simple(real_path):
        return True
    for environment in find_system_environments():
        if environment.executable == real_path:
            return True
        if environment._sha256 == _calculate_sha256_for_file(real_path):
            return True
    return False

jedi.api.environment._is_unix_safe_simpl:
def _is_unix_safe_simple(real_path):
    if _is_unix_admin():
        return any((real_path.startswith(p) for p in _SAFE_PATHS))
    uid = os.stat(real_path).st_uid
    return uid == 0

jedi.api.environment.get_system_environm:
def get_system_environment(version, *, env_vars=None):
    """
    Return the first Python environment found for a string of the form 'X.Y'
    where X and Y are the major and minor versions of Python.

    :raises: :exc:`.InvalidPythonEnvironment`
    :returns: :class:`.Environment`
    """
    exe = which('python' + version)
    if exe:
        if exe == sys.executable:
            return SameEnvironment()
        return Environment(exe)
    if os.name == 'nt':
        for exe in _get_executables_from_windows_registry(version):
            try:
                return Environment(exe, env_vars=env_vars)
            except InvalidPythonEnvironment:
                pass
    raise InvalidPythonEnvironment('Cannot find executable python%s.' % version)

parso.python.tokenize.tokenize_lines:
def tokenize_lines(lines: Iterable[str], *, version_info: Tuple[(int, int)], indents: List[int] = None, start_pos: Tuple[(int, int)] = (1, 0), is_first_token=True) -> Iterator[PythonToken]:
    """
    A heavily modified Python standard library tokenizer.

    Additionally to the default information, yields also the prefix of each
    token. This idea comes from lib2to3. The prefix contains all information
    that is irrelevant for the parser like newlines in parentheses or comments.
    """

    def dedent_if_necessary(start):
        while start < indents[-1]:
            if start > indents[-2]:
                yield PythonToken(ERROR_DEDENT, '', (lnum, start), '')
                indents[-1] = start
                break
            indents.pop()
            yield PythonToken(DEDENT, '', spos, '')
    (pseudo_token, single_quoted, triple_quoted, endpats, whitespace, fstring_pattern_map, always_break_tokens) = _get_token_collection(version_info)
    paren_level = 0
    if indents is None:
        indents = [0]
    max_ = 0
    numchars = '0123456789'
    contstr = ''
    contline: str
    contstr_start: Tuple[(int, int)]
    endprog: Pattern
    new_line = True
    prefix = ''
    additional_prefix = ''
    lnum = start_pos[0] - 1
    fstring_stack: List[FStringNode] = []
    for line in lines:
        lnum += 1
        pos = 0
        max_ = len(line)
        if is_first_token:
            if line.startswith(BOM_UTF8_STRING):
                additional_prefix = BOM_UTF8_STRING
                line = line[1:]
                max_ = len(line)
            line = '^' * start_pos[1] + line
            pos = start_pos[1]
            max_ += start_pos[1]
            is_first_token = False
        if contstr:
            endmatch = endprog.match(line)
            if endmatch:
                pos = endmatch.end(0)
                yield PythonToken(STRING, contstr + line[:pos], contstr_start, prefix)
                contstr = ''
                contline = ''
            else:
                contstr = contstr + line
                contline = contline + line
                continue
        while pos < max_:
            if fstring_stack:
                tos = fstring_stack[-1]
                if not tos.is_in_expr():
                    (string, pos) = _find_fstring_string(endpats, fstring_stack, line, lnum, pos)
                    if string:
                        yield PythonToken(FSTRING_STRING, string, tos.last_string_start_pos, prefix='')
                        tos.previous_lines = ''
                        continue
                    if pos == max_:
                        break
                rest = line[pos:]
                (fstring_end_token, additional_prefix, quote_length) = _close_fstring_if_necessary(fstring_stack, rest, lnum, pos, additional_prefix)
                pos += quote_length
                if fstring_end_token is not None:
                    yield fstring_end_token
                    continue
            if fstring_stack:
                string_line = line
                for fstring_stack_node in fstring_stack:
                    quote = fstring_stack_node.quote
                    end_match = endpats[quote].match(line, pos)
                    if end_match is not None:
                        end_match_string = end_match.group(0)
                        if len(end_match_string) - len(quote) + pos < len(string_line):
                            string_line = line[:pos] + end_match_string[:-len(quote)]
                pseudomatch = pseudo_token.match(string_line, pos)
            else:
                pseudomatch = pseudo_token.match(line, pos)
            if pseudomatch:
                prefix = additional_prefix + pseudomatch.group(1)
                additional_prefix = ''
                (start, pos) = pseudomatch.span(2)
                spos = (lnum, start)
                token = pseudomatch.group(2)
                if token == '':
                    assert prefix
                    additional_prefix = prefix
                    break
                initial = token[0]
            else:
                match = whitespace.match(line, pos)
                initial = line[match.end()]
                start = match.end()
                spos = (lnum, start)
            if (new_line and initial not in '\r\n#' and ((initial != '\\' or pseudomatch is None))):
                new_line = False
                if (paren_level == 0 and not fstring_stack):
                    indent_start = start
                    if indent_start > indents[-1]:
                        yield PythonToken(INDENT, '', spos, '')
                        indents.append(indent_start)
                    yield from dedent_if_necessary(indent_start)
            if not pseudomatch:
                match = whitespace.match(line, pos)
                if (new_line and paren_level == 0 and not fstring_stack):
                    yield from dedent_if_necessary(match.end())
                pos = match.end()
                new_line = False
                yield PythonToken(ERRORTOKEN, line[pos], (lnum, pos), additional_prefix + match.group(0))
                additional_prefix = ''
                pos += 1
                continue
            if (initial in numchars or (initial == '.' and token != '.' and token != '...')):
                yield PythonToken(NUMBER, token, spos, prefix)
            elif pseudomatch.group(3) is not None:
                if (token in always_break_tokens and ((fstring_stack or paren_level))):
                    fstring_stack[:] = []
                    paren_level = 0
                    m = re.match('[ \\f\\t]*$', line[:start])
                    if m is not None:
                        yield from dedent_if_necessary(m.end())
                if token.isidentifier():
                    yield PythonToken(NAME, token, spos, prefix)
                else:
                    yield from _split_illegal_unicode_name(token, spos, prefix)
            elif initial in '\r\n':
                if any((not f.allow_multiline() for f in fstring_stack)):
                    fstring_stack.clear()
                if (not new_line and paren_level == 0 and not fstring_stack):
                    yield PythonToken(NEWLINE, token, spos, prefix)
                else:
                    additional_prefix = prefix + token
                new_line = True
            elif initial == '#':
                assert (not token.endswith('\n') and not token.endswith('\r'))
                if (fstring_stack and fstring_stack[-1].is_in_expr()):
                    yield PythonToken(ERRORTOKEN, initial, spos, prefix)
                    pos = start + 1
                else:
                    additional_prefix = prefix + token
            elif token in triple_quoted:
                endprog = endpats[token]
                endmatch = endprog.match(line, pos)
                if endmatch:
                    pos = endmatch.end(0)
                    token = line[start:pos]
                    yield PythonToken(STRING, token, spos, prefix)
                else:
                    contstr_start = spos
                    contstr = line[start:]
                    contline = line
                    break
            elif (initial in single_quoted or token[:2] in single_quoted or token[:3] in single_quoted):
                if token[-1] in '\r\n':
                    contstr_start = (lnum, start)
                    endprog = (endpats.get(initial) or endpats.get(token[1]) or endpats.get(token[2]))
                    contstr = line[start:]
                    contline = line
                    break
                else:
                    yield PythonToken(STRING, token, spos, prefix)
            elif token in fstring_pattern_map:
                fstring_stack.append(FStringNode(fstring_pattern_map[token]))
                yield PythonToken(FSTRING_START, token, spos, prefix)
            elif (initial == '\\' and line[start:] in ('\\\n', '\\\r\n', '\\\r')):
                additional_prefix += prefix + line[start:]
                break
            else:
                if token in '([{':
                    if fstring_stack:
                        fstring_stack[-1].open_parentheses(token)
                    else:
                        paren_level += 1
                elif token in ')]}':
                    if fstring_stack:
                        fstring_stack[-1].close_parentheses(token)
                    elif paren_level:
                        paren_level -= 1
                elif (token.startswith(':') and fstring_stack and fstring_stack[-1].parentheses_count - fstring_stack[-1].format_spec_count == 1):
                    fstring_stack[-1].format_spec_count += 1
                    token = ':'
                    pos = start + 1
                yield PythonToken(OP, token, spos, prefix)
    if contstr:
        yield PythonToken(ERRORTOKEN, contstr, contstr_start, prefix)
        if (contstr.endswith('\n') or contstr.endswith('\r')):
            new_line = True
    if fstring_stack:
        tos = fstring_stack[-1]
        if tos.previous_lines:
            yield PythonToken(FSTRING_STRING, tos.previous_lines, tos.last_string_start_pos, prefix='')
    end_pos = (lnum, max_)
    for indent in indents[1:]:
        indents.pop()
        yield PythonToken(DEDENT, '', end_pos, '')
    yield PythonToken(ENDMARKER, '', end_pos, additional_prefix)

parso.python.tokenize._find_fstring_stri:
def _find_fstring_string(endpats, fstring_stack, line, lnum, pos):
    tos = fstring_stack[-1]
    allow_multiline = tos.allow_multiline()
    if tos.is_in_format_spec():
        if allow_multiline:
            regex = fstring_format_spec_multi_line
        else:
            regex = fstring_format_spec_single_line
    elif allow_multiline:
        regex = fstring_string_multi_line
    else:
        regex = fstring_string_single_line
    match = regex.match(line, pos)
    if match is None:
        return (tos.previous_lines, pos)
    if not tos.previous_lines:
        tos.last_string_start_pos = (lnum, pos)
    string = match.group(0)
    for fstring_stack_node in fstring_stack:
        end_match = endpats[fstring_stack_node.quote].match(string)
        if end_match is not None:
            string = end_match.group(0)[:-len(fstring_stack_node.quote)]
    new_pos = pos
    new_pos += len(string)
    if (string.endswith('\n') or string.endswith('\r')):
        tos.previous_lines += string
        string = ''
    else:
        string = tos.previous_lines + string
    return (string, new_pos)

parso.python.tokenize._split_illegal_uni:
def _split_illegal_unicode_name(token, start_pos, prefix):

    def create_token():
        return PythonToken((ERRORTOKEN if is_illegal else NAME), found, pos, prefix)
    found = ''
    is_illegal = False
    pos = start_pos
    for (i, char) in enumerate(token):
        if is_illegal:
            if char.isidentifier():
                yield create_token()
                found = char
                is_illegal = False
                prefix = ''
                pos = (start_pos[0], start_pos[1] + i)
            else:
                found += char
        else:
            new_found = found + char
            if new_found.isidentifier():
                found = new_found
            else:
                if found:
                    yield create_token()
                    prefix = ''
                    pos = (start_pos[0], start_pos[1] + i)
                found = char
                is_illegal = True
    if found:
        yield create_token()

jedi.inference.star_args._iter_nodes_for:
def _iter_nodes_for_param(param_name):
    from parso.python.tree import search_ancestor
    from jedi.inference.arguments import TreeArguments
    execution_context = param_name.parent_context
    function_node = tree.search_ancestor(param_name.tree_name, 'funcdef', 'lambdef')
    module_node = function_node.get_root_node()
    start = function_node.children[-1].start_pos
    end = function_node.children[-1].end_pos
    for name in module_node.get_used_names().get(param_name.string_name):
        if start <= name.start_pos < end:
            argument = name.parent
            if (argument.type == 'argument' and argument.children[0] == '*' * param_name.star_count):
                trailer = search_ancestor(argument, 'trailer')
                if trailer is not None:
                    context = execution_context.create_context(trailer)
                    if _goes_to_param_name(param_name, context, name):
                        values = _to_callables(context, trailer)
                        args = TreeArguments.create_cached(execution_context.inference_state, context=context, argument_node=trailer.children[1], trailer=trailer)
                        for c in values:
                            yield (c, args)

jedi.inference.star_args._remove_given_p:
def _remove_given_params(arguments, param_names):
    count = 0
    used_keys = set()
    for (key, _) in arguments.unpack():
        if key is None:
            count += 1
        else:
            used_keys.add(key)
    for p in param_names:
        if (count and p.maybe_positional_argument()):
            count -= 1
            continue
        if (p.string_name in used_keys and p.maybe_keyword_argument()):
            continue
        yield p
